BEGIN;

-- Keep unverified signup details outside the application account tables.
-- Supabase Auth still creates an unconfirmed auth.users row so it can issue
-- its email OTP; the platform's person/member records are created only after
-- that OTP (or the shared two-address code) is accepted.
CREATE TABLE "signup_verification" (
    "signup_verification_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "auth_user_id" UUID NOT NULL,
    "full_name" VARCHAR(255) NOT NULL,
    "email_personal" VARCHAR(255) NOT NULL,
    "email_university" VARCHAR(255),
    "registration_type" VARCHAR(20) NOT NULL,
    "application_data" JSONB NOT NULL,
    "committees" JSONB NOT NULL DEFAULT '[]',
    "global_roles" JSONB NOT NULL DEFAULT '[]',
    "code_hash" VARCHAR(64),
    "sent_at" TIMESTAMPTZ(6),
    "code_expires_at" TIMESTAMPTZ(6),
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "verified_at" TIMESTAMPTZ(6),
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),
    CONSTRAINT "signup_verification_pkey" PRIMARY KEY ("signup_verification_id"),
    CONSTRAINT "signup_verification_attempts_check" CHECK ("attempts" >= 0)
);

CREATE UNIQUE INDEX "signup_verification_auth_user_id_key" ON "signup_verification"("auth_user_id");
CREATE UNIQUE INDEX "signup_verification_email_personal_key" ON "signup_verification"("email_personal");
CREATE UNIQUE INDEX "signup_verification_email_university_key" ON "signup_verification"("email_university");
CREATE INDEX "signup_verification_expires_at_idx" ON "signup_verification"("expires_at");

COMMIT;
